  sol: 's = input().strip()\nson = {}\nsol = 0\nen_iyi = 0\nfor i, c in enumerate(s):\n    if c in son and son[c] >= sol:\n        sol = son[c] + 1\n    son[c] = i\n    if i - sol + 1 > en_iyi:\n        en_iyi = i - sol + 1\nprint(en_iyi)\n',
