  sol: 'import numpy as np\n\nn = int(input())\na = np.array(input().split(), dtype=float)\nprint(f"ortalama: {a.mean():.2f}")\nprint(f"std: {a.std():.2f}")\nprint(f"aralik: {a.min():.2f} {a.max():.2f}")\n',
  editorial: '<p><b>Dönüşüm:</b> <code>np.array(input().split(), dtype=float)</code> metin listesini tek adımda float dizisine çevirir; <code>np.fromstring</code> eskimiş (deprecated) bir yoldur.</p><p><b>ddof:</b> NumPy\'ın <code>std()</code> varsayılanı <code>ddof=0</code> (popülasyon), pandas\'ın <code>std()</code> varsayılanı <code>ddof=1</code> (örneklem). Aynı veride iki kütüphane farklı sonuç verirse ilk bakılacak yer burasıdır.</p><p><b>Biçim:</b> <code>-0.00</code> yazımı biçimlendirmede görülebilir; burada testler sıfır ortalamalı veriyi doğrudan 0 ile verdiği için sorun yok.</p>',
  hints: ['<code>np.array(input().split(), dtype=float)</code>', '<code>a.mean()</code>, <code>a.std()</code>, <code>a.min()</code>, <code>a.max()</code>', '<code>f"{x:.2f}"</code>']
